package com.hmdp.ai.runtime.node;
import com.fasterxml.jackson.databind.*;import com.hmdp.ai.application.dto.agent.AgentInputRequest;import com.hmdp.ai.domain.run.AgentRunOutput;import com.hmdp.ai.domain.workflow.WorkflowNodeType;import com.hmdp.ai.runtime.model.AgentModelExecutionPort;import org.springframework.stereotype.Component;import java.util.*;
@Component public class LlmNodeExecutor implements NodeExecutor {private final AgentModelExecutionPort model;private final ObjectMapper mapper;public LlmNodeExecutor(AgentModelExecutionPort m,ObjectMapper mapper){model=m;this.mapper=mapper;}public Set<WorkflowNodeType>supportedTypes(){return Collections.singleton(WorkflowNodeType.LLM);}public NodeExecutionResult execute(NodeExecutionContext c){Object raw=c.getVariables().get("input");AgentInputRequest input=mapper.convertValue(raw,AgentInputRequest.class);AgentRunOutput out=model.execute(c.getAgent(),c.getExecutionContext(),input);Map<String,Object>u=new LinkedHashMap<>();u.put("agentOutput",out);return NodeExecutionResult.success(mapper.valueToTree(out),null,u);}}
